    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")
    zookeeper_patches = image_patch.find("zookeeper")

    if not giraffe_patches or not zookeeper_patches:
        return image_patch

    # Find the head of the giraffe
    def find_head(patches):
        heads = [p for p in patches if p.llm_query("What is the object?") == "head"]
        return heads[0] if heads else None

    giraffe_head_patch = find_head(giraffe_patches)
