    # Check if the head of the giraffe is behind the zookeeper
    def is_behind(head, zookeeper):
        return head.compute_depth() < zookeeper.compute_depth()

    zookeeper_patch = find_head(zookeeper_patches)
    if is_behind(giraffe_head_patch, zookeeper_patch):
        return giraffe_head_patch
    else:
        return zookeeper_patch

